ruby -rjson -rdigest -e '
base=ARGV.fetch(0)
receipt=JSON.parse(File.read(File.join(base,"final-verification.json")))
pins=receipt.fetch("commands").first.fetch("result").fetch("hashes")
pins.each{|name,want| p=File.join(base,name); raise "changed pinned input" unless File.size(p)==want.fetch("bytes") && Digest::SHA256.file(p).hexdigest==want.fetch("sha256")}
links=File.read(File.join(base,"report.md")).scan(/\]\(([^)]+)\)/).flatten.reject{|x| x.start_with?("https://","http://","#")}
raise "broken local report link" unless links.all?{|x| File.exist?(File.expand_path(x.split("#").first,base))}
json=Dir.glob(File.join(base,"**","*.json")); json.each{|p| JSON.parse(File.read(p))}
raise "unexpected media" unless Dir.children(File.join(base,"media")).empty?
puts JSON.generate({status:"pass",stage_json_files:json.size,report_local_links:links.size,pinned_files:pins.size,media_files:0})
